import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import {
  checkHistoryCard2,
  HISTORY_CARD_FINDINGS,
  historyPositions,
  MAX_HISTORY_WINDOW,
} from "../src/history-card.js";

// history_card/2 (ER -03 §8.1.2) against vectors/evidence-request/history-card-2.json
// (generated by python/scripts/generate_evidence_request_vectors.py).
const FILE = resolve(
  process.cwd(),
  "..",
  "vectors",
  "evidence-request",
  "history-card-2.json",
);

type Case = {
  id: string;
  card: unknown;
  anchor: string;
  expect: { valid: boolean; finding: string | null };
};
const corpus = JSON.parse(readFileSync(FILE, "utf8")) as {
  draft: string;
  count: number;
  findings: string[];
  max_window: number;
  log_keys: string[];
  positions: { n: number; window: number; positions: number[] }[];
  cases: Case[];
};

describe("history_card/2 vectors", () => {
  it("reads the -03 corpus header", () => {
    expect(corpus.draft).toBe("draft-mih-agent-evidence-request-03");
    expect(corpus.cases).toHaveLength(corpus.count);
    expect(corpus.findings).toEqual([...HISTORY_CARD_FINDINGS]);
    expect(corpus.max_window).toBe(MAX_HISTORY_WINDOW);
  });

  it.each(corpus.positions.map((r) => [`n${r.n}-w${r.window}`, r] as const))(
    "positions %s",
    (_id, row) => {
      expect(historyPositions(row.n, row.window)).toEqual(row.positions);
    },
  );

  it.each(corpus.cases.map((c) => [c.id, c] as const))("%s", async (_id, c) => {
    const finding = await checkHistoryCard2(c.card, c.anchor, corpus.log_keys);
    expect(finding).toBe(c.expect.finding);
    expect(finding === null).toBe(c.expect.valid);
  });

  it("has a case for every finding", () => {
    const seen = new Set(
      corpus.cases.map((c) => c.expect.finding).filter((f) => f !== null),
    );
    expect(seen).toEqual(new Set(HISTORY_CARD_FINDINGS));
  });

  it("bounds the positions by W + floor(log2 n) + 2", () => {
    for (const n of [1, 2, 5, 100, 1023, 1024, 4097, 1_000_000, 2 ** 40 + 3])
      for (const w of [1, 2, 8, 64]) {
        const got = historyPositions(n, w);
        expect(got[0]).toBe(0);
        expect(got[got.length - 1]).toBe(n);
        expect(got.length).toBeLessThanOrEqual(
          w + Math.floor(Math.log2(n)) + 2,
        );
      }
  });
});
